SELECT p.p_promo_id, p.p_promo_name, SUM(cs.cs_ext_sales_price) AS total_sales, SUM(cs.cs_ext_discount_amt) AS total_discount, AVG(cs.cs_ext_discount_amt) AS avg_discount_per_sale, SUM(cs.cs_net_profit) AS total_net_profit, CASE WHEN SUM(cs.cs_ext_discount_amt) / NULLIF(SUM(cs.cs_ext_sales_price),0) > 0.2 THEN 'High Discount' ELSE 'Low/Medium Discount' END AS discount_category, COUNT(DISTINCT CASE WHEN p.p_channel_email = 'Y' THEN p.p_promo_id END) AS email_channel_sales, COUNT(DISTINCT CASE WHEN p.p_channel_tv = 'Y' THEN p.p_promo_id END) AS tv_channel_sales, DENSE_RANK() OVER (ORDER BY SUM(cs.cs_net_profit) DESC) AS profit_rank FROM catalog_sales cs JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN warehouse w ON cs.cs_warehouse_sk = w.w_warehouse_sk GROUP BY p.p_promo_id, p.p_promo_name HAVING SUM(cs.cs_ext_sales_price) > 5000 ORDER BY profit_rank
